        for (int i = x - 2; i <= x; ++i) {
            for (int j = y - 2; j <= y; ++j) {
                if (a[i][j] == '.') {
                    a[i][j] = '!';
                }
            }
        }
    } else {
        for (int i = 1; i <= 9; ++i) {
            for (int j = 1; j <= 9; ++j) {
                if (a[i][j] == '.') {
                    a[i][j] = '!';
                }
            }
        }
    }

    for (int i = 1; i <= 9; ++i) {
        for (int j = 1; j <= 9; ++j) {
            cout << a[i][j];
